-- Phase Two Lesson 1.5 study workbook; no future early release.
update public.aca_phase_two_workbook_definitions
set content=jsonb_set(content,'{pages}',coalesce(content->'pages','[]'::jsonb)||'{"number":5,"lesson_id":"1.5","kicker":"JOURNEY ONE / LESSON 1.5","title":"Scope a Solution and a Project Worth Completing","blocks":[{"type":"heading","text":"A solution concept is not deployment approval"},{"type":"text","text":"Your investigation from Lessons 1.1–1.4 already identifies a person, a need, evidence, a narrow AI role, a value hypothesis and a responsible decision. Lesson 1.5 turns that foundation into one finishable artifact. Describe problem, people, outcome, current workflow, AI role or no AI, human owner, approved information, possible value, risks, boundaries and test question. A solution concept does not authorize real-world deployment."},{"type":"note","title":"The Academy FOCUS Capstone Frame","text":"Function — what does the first artifact do? Owner — who reviews and approves it? Customer — who benefits? Use Case — what specific situation, input and output does it cover? Scope — what is included, intentionally excluded and dependent on permission?","theme":"gold"},{"type":"heading","text":"One small professional result"},{"type":"text","text":"A modest complete artifact can demonstrate more than an unfinished elaborate business plan. The fictional proposal assistant in this lesson may draft one kind of estimate using approved sample inputs. It must exclude contract approval, payment collection, unapproved prices and unsupported promises."},{"type":"heading","text":"Compare three possible artifacts"},{"type":"field","id":"p2-j1-5-artifact1","label":"Artifact candidate 1: describe the output, realistic time, available tools, likely usefulness and consequence of errors.","hint":"Treat demand, costs and approvals as unknown if you lack evidence.","lines":4},{"type":"field","id":"p2-j1-5-artifact2","label":"Artifact candidate 2: describe the output, feasibility, value, risks and permissions.","hint":"","lines":4},{"type":"field","id":"p2-j1-5-artifact3","label":"Artifact candidate 3: describe the output, dependencies, consequences, expected effort and limits.","hint":"","lines":4},{"type":"field","id":"p2-j1-5-selection","label":"Which one is your first capstone artifact? Why can you finish and verify it?","hint":"Record why the other two will wait.","lines":4},{"type":"heading","text":"Write your FOCUS frame"},{"type":"field","id":"p2-j1-5-function","label":"Function — state in one sentence exactly what your artifact does.","hint":"","lines":4},{"type":"field","id":"p2-j1-5-owner","label":"Owner — who has responsibility for reviewing and approving the result?","hint":"","lines":4},{"type":"field","id":"p2-j1-5-customer","label":"Customer — who uses or benefits from it?","hint":"Clearly label a simulated or fictional customer.","lines":4},{"type":"field","id":"p2-j1-5-usecase","label":"Use Case — describe the actual situation, permitted sample input and expected output.","hint":"","lines":4},{"type":"field","id":"p2-j1-5-scope","label":"Scope — list what you will build now, and what is specifically excluded.","hint":"Do not assume approval to collect payments, send customer messages or use private data.","lines":4},{"type":"heading","text":"Create the solution concept"},{"type":"field","id":"p2-j1-5-current","label":"What need and current workflow are you improving?","hint":"Carry forward the authorized evidence from Lesson 1.2.","lines":4},{"type":"field","id":"p2-j1-5-role","label":"What narrow AI role, direct non-AI step and human review are appropriate?","hint":"","lines":4},{"type":"field","id":"p2-j1-5-inputs","label":"What tools, example information, permission and resources are actually available?","hint":"","lines":4},{"type":"field","id":"p2-j1-5-success","label":"What evidence will count as finished and useful?","hint":"State observable output quality rather than inflated outcomes.","lines":4},{"type":"field","id":"p2-j1-5-exclusions","label":"What must the first version NOT do?","hint":"State decisions and dependencies that require someone else''s approval.","lines":4},{"type":"heading","text":"Review with your chosen AI assistant"},{"type":"text","text":"Open ChatGPT or another chosen AI assistant on a computer, tablet or phone. Enter only public, fictional or approved sanitized project notes. Ask it to apply Function, Owner, Customer, Use Case and Scope. Inspect missing fields and suggestions for a smaller artifact. Reject imaginary dependencies, unsupported benefits or assumed deployment permission."},{"type":"note","title":"Copyable approved AI request","text":"Review this project using Function, Owner, Customer, Use Case and Scope. Identify missing solution-concept fields and suggest a smaller complete artifact where needed. Do not assume approval to deploy. Draft: [sanitized charter].","theme":"gold"},{"type":"field","id":"p2-j1-5-ai-review","label":"What did AI suggest that you corrected, narrowed or refused?","hint":"Name one unsupported dependency, assumption or approval.","lines":4},{"type":"heading","text":"Write a finishable charter and test"},{"type":"field","id":"p2-j1-5-charter","label":"Write your one-paragraph capstone charter: person, need, function, owner, outcome, scope and boundaries.","hint":"The charter should be understandable to a human reviewer.","lines":4},{"type":"field","id":"p2-j1-5-test","label":"Describe one realistic first test: safe input, expected output, human check, failure condition and when it will be conducted.","hint":"Only test with fictional or appropriately authorized inputs.","lines":4},{"type":"field","id":"p2-j1-5-permissions","label":"What decision, tool or information requires another person''s approval?","hint":"Do not treat a training exercise as authorization.","lines":4},{"type":"field","id":"p2-j1-5-check","label":"Explain what counts as complete and what is deliberately outside scope.","hint":"","lines":4},{"type":"note","title":"Preserve your professional evidence","text":"Save the charter, three options, initial solution concept, exclusions, permissions and first test to your continuing Project Record. These workbook notes remain yours to review, print or download once released. Lesson 1.6 content is unavailable until its scheduled release.","theme":"gold"}]}'::jsonb,true),version=version+1,updated_at=now()
where journey_number=1 and not exists(select 1 from jsonb_array_elements(content->'pages') p where p->>'lesson_id'='1.5');
